-- ============================================================
-- Quiz coverage for databases/mongodb and databases/cassandra
-- (overview, fundamentals, intermediate, advanced -- all four
-- tabs exist and carry substantive live content for both).
-- Phase 4 (Databases academy), batch 4: MongoDB & Cassandra.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/mongodb/overview ----------
('databases', 'mongodb', 'overview', 'Is it accurate to say MongoDB "can''t do ACID transactions" and is therefore never suitable for financial-style data?', '["Yes, this is completely accurate and has always been true", "No -- MongoDB has supported multi-document ACID transactions since version 4.0 (2018, single replica set) and 4.2 (sharded clusters); the real reasons financial systems often still prefer relational databases are usually schema rigidity, mature reporting/JOIN tooling, and organizational familiarity, not a technical ACID limitation that no longer exists", "MongoDB only supports ACID transactions within a single document, never across documents", "ACID transactions in MongoDB require a separate paid enterprise license"]', 1, 'This is a genuinely common but outdated claim -- treating it as still true is one of the most common stale assumptions people carry about MongoDB.', 'beginner'),
('databases', 'mongodb', 'overview', 'What is the key structural difference between a MongoDB document and a SQL row?', '["They are functionally identical, just with different naming", "A MongoDB document can have nested objects and arrays built directly into it, and different documents in the same collection can have different structures -- a SQL row is rigid, with every row in a table sharing the exact same columns", "SQL rows can contain nested objects, but MongoDB documents cannot", "MongoDB documents cannot contain arrays under any circumstances"]', 1, 'This structural flexibility is the core reason MongoDB fits evolving schemas and nested data well, but it also means MongoDB doesn''t enforce a shared structure across documents the way a SQL table''s columns do.', 'beginner'),
('databases', 'mongodb', 'overview', 'In `db.users.find({ age: { $gte: 25 } }).toArray()`, what does `$gte` do?', '["It deletes documents where age is greater than or equal to 25", "It is a query operator meaning \"greater than or equal to\" -- the query matches documents where the age field is 25 or higher", "It sorts the results by age in descending order", "It is a MongoDB-specific aggregation stage, not usable in find()"]', 1, 'MongoDB''s query operators like $gte, $gt, $lt, $lte are the standard way to express range conditions in a find() query, analogous to >=, >, <, <= in SQL.', 'beginner'),
('databases', 'mongodb', 'overview', 'What does the aggregation pipeline stage `$bucket` do?', '["It deletes documents outside a specified range", "It groups documents into ranges (buckets) based on a specified field, similar to a histogram -- useful for grouping values like price into ranges such as 0-50, 50-100, etc.", "It creates a backup of the collection", "It is used only for full-text search indexing"]', 1, '$bucket is specifically designed for range-based grouping/histogram-style aggregation, distinct from $group which groups by exact matching values.', 'intermediate'),
('databases', 'mongodb', 'overview', 'Where does MongoDB sit on the CAP theorem, and what does that mean in practice for its default write concern?', '["MongoDB guarantees all three of Consistency, Availability, and Partition tolerance simultaneously with no tradeoffs", "MongoDB prioritizes Consistency and Partition tolerance (CP) -- with the default write concern w:1, a write is acknowledged once the primary confirms it, meaning replicas may briefly lag; w:majority requires acknowledgment from most replica set members for stronger consistency at the cost of higher latency", "MongoDB is purely an AP (Available + Partition tolerant) system with no consistency guarantees available", "CAP theorem does not apply to MongoDB since it is not a distributed system"]', 1, 'Understanding where MongoDB sits on CAP, and how write concern settings trade off latency against replication guarantees, is a foundational MongoDB interview topic.', 'intermediate'),

-- ---------- databases/mongodb/fundamentals ----------
('databases', 'mongodb', 'fundamentals', 'What does `db.users.updateOne({ email: ''alice@example.com'' }, { $set: { age: 31 } })` do if no matching document exists?', '["It throws an error and halts execution", "It does nothing by default -- no document is created or modified, since updateOne only affects an existing matching document unless the upsert option is explicitly set to true", "It automatically creates a new document with just the age field", "It updates every document in the collection instead"]', 1, 'This is an important distinction from an upsert -- updateOne without { upsert: true } is a strict update-only operation that silently matches zero documents if none exist.', 'beginner'),
('databases', 'mongodb', 'fundamentals', 'What is the practical difference between $push and $addToSet when modifying an array field?', '["They are identical in every case", "$push appends a value to an array regardless of whether it already exists (allowing duplicates); $addToSet only appends the value if it is not already present in the array, effectively enforcing uniqueness within that array", "$addToSet can only be used on numeric arrays", "$push requires the array to already contain at least one element"]', 1, 'Choosing between these matters specifically when duplicate values in an array field would be incorrect -- $addToSet is the right choice whenever the array is meant to represent a set of unique values.', 'beginner'),
('databases', 'mongodb', 'fundamentals', 'Why does a connection pool matter for a MongoDB application the same way it does for a relational database?', '["MongoDB does not support connection pooling at all", "Opening a new database connection per request is expensive relative to the query itself -- a pool reuses a smaller set of already-established connections, avoiding that repeated overhead under real application load, the same underlying reason connection pooling matters for any database", "Connection pooling is only relevant for sharded MongoDB clusters, never single instances", "Pooling in MongoDB automatically caches query results, unlike relational database pools"]', 1, 'This tradeoff isn''t MongoDB-specific -- it''s the same general database-connection-cost reasoning that applies broadly, and MongoDB drivers support connection pooling for exactly this reason.', 'beginner'),
('databases', 'mongodb', 'fundamentals', 'What is the N+1 query problem, and does it apply to MongoDB the same way it applies to a relational database with an ORM?', '["N+1 only exists in relational databases and cannot occur when using MongoDB", "N+1 is fetching a list of N records with one query, then issuing a separate query per record for related data -- this application-layer pattern can happen with MongoDB too if related documents are fetched one at a time in a loop instead of using $lookup or a single batched query", "N+1 refers to a MongoDB-specific replication lag issue, unrelated to query counts", "MongoDB automatically prevents N+1 patterns through its document model"]', 1, 'The N+1 problem is a general application-layer anti-pattern, not tied to any specific database technology -- MongoDB''s $lookup aggregation stage is one of the tools available to avoid it by joining related data in a single query.', 'intermediate'),
('databases', 'mongodb', 'fundamentals', 'What does a compound index like `db.col.createIndex({ a: 1, b: -1 })` support, and what query pattern does it NOT efficiently support?', '["It supports every possible query on fields a and b equally well, regardless of which fields are filtered", "Like a composite index in a relational database, a compound index is most useful for queries filtering on a left-to-right prefix of its fields (a alone, or a and b together) -- a query filtering only on b, skipping a, generally cannot use this index efficiently", "Compound indexes cannot mix ascending and descending sort directions", "This index only works for aggregation pipelines, not find() queries"]', 1, 'The same leftmost-prefix principle from relational composite indexes applies to MongoDB compound indexes -- field order in the index definition determines which query patterns it can actually accelerate.', 'intermediate'),

-- ---------- databases/mongodb/intermediate ----------
('databases', 'mongodb', 'intermediate', 'In an aggregation pipeline, what does `$lookup` accomplish, and how is it different from a SQL JOIN?', '["$lookup deletes documents that don''t have a match in another collection", "$lookup performs a left outer join-style operation, pulling matching documents from another collection into the current pipeline as an array field -- unlike a SQL JOIN, the result is a nested array embedded in each document rather than a flattened row-per-match result", "$lookup can only match on the _id field", "$lookup requires the two collections to have identical schemas"]', 1, 'Understanding that $lookup produces a nested array (often followed by $unwind to flatten it) rather than SQL''s flat joined-row output is key to using it correctly in a pipeline.', 'intermediate'),
('databases', 'mongodb', 'intermediate', 'What problem do MongoDB Change Streams solve, and what is a common real-world use case?', '["They provide a way to permanently archive old documents", "Change Streams let an application react to database changes (inserts, updates, deletes) in real time without polling -- common use cases include cache invalidation, triggering notifications, and event-driven architectures reacting to data changes as they happen", "Change Streams are used exclusively for schema migration", "Change Streams replace the need for indexes on frequently queried fields"]', 1, 'The real-time, no-polling nature of Change Streams is what makes them valuable for reactive patterns like cache invalidation and notifications that would otherwise require inefficient periodic polling.', 'intermediate'),
('databases', 'mongodb', 'intermediate', 'Why does a MongoDB multi-document transaction generally cost more in performance than a well-designed single-document write?', '["Multi-document transactions are not actually more expensive than single-document writes", "A multi-document transaction has to coordinate atomicity guarantees across multiple documents (and potentially multiple shards), which carries real overhead compared to a single-document write, which is atomic by default at no extra cost -- this is exactly why MongoDB''s own guidance recommends favoring single-document atomicity via good schema design where possible", "Transactions are slower only because they require a separate database license", "Single-document writes are never atomic in MongoDB, so this comparison doesn''t apply"]', 1, 'This is a genuinely practical design implication -- knowing that single-document atomicity is \"free\" while multi-document transactions have a real coordination cost should inform schema design decisions, not just transaction usage decisions.', 'advanced'),
('databases', 'mongodb', 'intermediate', 'What does the aggregation stage `$facet` let you do that running several separate `$group` queries would not?', '["$facet deletes duplicate results across multiple queries", "$facet runs multiple independent aggregation sub-pipelines in parallel within a single overall aggregate() call, returning all their results together -- useful for faceted search UIs that need several different groupings (by category, by brand, by price range) computed from the same filtered dataset in one round trip", "$facet can only be used with the $match stage and no others", "$facet is a deprecated stage, replaced entirely by $bucket"]', 1, 'Computing several groupings in one $facet call, rather than several separate round trips to the database, is specifically valuable for UI patterns like faceted search filters shown together.', 'intermediate'),
('databases', 'mongodb', 'intermediate', 'Why does `db.orders.insertOne(doc, { session })` inside a `session.withTransaction()` block matter for a multi-step operation like creating an order and deducting inventory?', '["The session parameter is optional decoration with no functional effect", "Passing the session ties each individual operation to the same transaction, so if any operation within the transaction throws (e.g. insufficient inventory), the whole set of operations is automatically rolled back together rather than leaving a partially-applied state (an order created without the corresponding inventory deduction)", "Sessions are only required for read operations, never writes", "withTransaction() automatically retries failed operations indefinitely without any error handling needed"]', 1, 'This is exactly the atomicity guarantee multi-document transactions exist to provide -- without passing the session consistently, the operations would not actually be part of the same atomic unit.', 'advanced'),

-- ---------- databases/mongodb/advanced ----------
('databases', 'mongodb', 'advanced', 'What replaced `rs.isMaster()`/`db.isMaster()` in current MongoDB, and why does this matter when following older tutorials?', '["Nothing replaced them -- they work identically in all MongoDB versions", "rs.isMaster()/db.isMaster() were deprecated starting in MongoDB 5.0 in favor of hello() -- the old commands still work as deprecated aliases, but a lot of older tutorials and reference material still show only the deprecated names", "isMaster() was renamed to isPrimary() specifically, not hello()", "This deprecation only applies to sharded clusters, not replica sets"]', 1, 'This mirrors a similar terminology-modernization pattern seen elsewhere (like MySQL''s master/slave replication renaming) -- worth knowing the current command exists even though the deprecated alias hasn''t been removed.', 'intermediate'),
('databases', 'mongodb', 'advanced', 'In `db.orders.insertOne(doc, { writeConcern: { w: "majority", j: true } })`, what do the `w` and `j` options each guarantee?', '["w controls read consistency, and j controls the query timeout", "w: \"majority\" requires acknowledgment from a majority of replica set members before the write is considered successful; j: true additionally requires the write to be journaled (written to the durability log) on the acknowledging nodes before returning success", "w and j are interchangeable settings that do the same thing", "These options only apply to sharded clusters, never single replica sets"]', 1, 'Write concern is a genuine, tunable tradeoff between durability guarantees and write latency -- w:\"majority\" plus j:true is a stronger (and slower) guarantee than the w:1 default.', 'advanced'),
('databases', 'mongodb', 'advanced', 'Why are low-cardinality or monotonically increasing shard keys considered bad choices when sharding a MongoDB collection?', '["Shard key choice has no real effect on data distribution", "A low-cardinality shard key (few distinct values) or a monotonically increasing one (like a creation timestamp) can concentrate writes onto a small number of shards -- creating \"hot spots\" where some shards handle disproportionate load while others sit comparatively idle, defeating the purpose of sharding", "Shard keys can always be changed later with no operational cost if the initial choice turns out to be wrong", "Hashed sharding always produces worse distribution than range sharding regardless of the underlying data"]', 1, 'This is exactly why hashed sharding on a naturally monotonic or low-cardinality field is often recommended over range sharding on that same field -- hashing spreads writes evenly even when the underlying values would otherwise cluster.', 'advanced'),
('databases', 'mongodb', 'advanced', 'What is the practical difference between a Physical/Primary-Secondary-Arbiter (PSA) and Primary-Secondary-Secondary (PSS) replica set configuration, and why is PSS generally preferred in production?', '["PSA and PSS provide identical failover guarantees -- the choice is purely about cost", "An Arbiter in a PSA configuration only votes in elections and holds no data, so it cannot be promoted to primary if a data-bearing node fails -- PSS, with two full data-bearing secondaries, ensures a real data-bearing node is always available to take over, which is why PSS is generally preferred despite costing more to run", "Arbiters actually hold a full copy of the data but are read-only", "PSA configurations cannot achieve any replication at all"]', 1, 'This distinction matters directly for real failover behavior -- a PSA setup can vote correctly in an election but still leave you without a viable new primary if the wrong node fails, which PSS avoids by keeping full data on every voting member.', 'advanced'),
('databases', 'mongodb', 'advanced', 'Why does the `background: true` option on `createIndex()` no longer have the significance it once did in current MongoDB versions?', '["The option was never valid syntax and always caused an error", "Since MongoDB 4.2, all index builds automatically use an optimized approach that allows concurrent reads/writes during the build, making the background option effectively a no-op that current MongoDB silently ignores -- a lot of older material still shows it as if it were still a meaningful choice", "background: true now causes index builds to fail on any collection larger than 1GB", "This option was replaced by a required foreground: false flag in MongoDB 6.0"]', 1, 'This is a genuinely common piece of outdated advice still found in older tutorials -- knowing it''s now a no-op (not harmful, just unnecessary) is useful for reading older material critically.', 'advanced'),

-- ---------- databases/cassandra/overview ----------
('databases', 'cassandra', 'overview', 'What does it mean that Cassandra uses a "ring architecture" with no master/slave relationship between nodes?', '["One node is always elected as a permanent leader for the entire cluster", "All nodes are equal, and data is distributed around a ring using consistent hashing, with each node responsible for a range of tokens -- any node can act as coordinator for any client request, unlike a primary/replica relational setup", "Ring architecture means data physically travels through every node before reaching its destination", "Only nodes in specific ring positions can accept write requests"]', 1, 'This masterless design is central to Cassandra''s high-availability story -- there is no single node whose failure blocks writes or reads for the whole cluster the way a relational primary''s failure would.', 'beginner'),
('databases', 'cassandra', 'overview', 'In CQL, why must a query''s WHERE clause include the partition key?', '["It is a stylistic convention, not an actual requirement", "The partition key determines which node(s) via consistent hashing own the requested data -- without it, Cassandra would need to scan across the entire cluster (scatter-gather) rather than routing directly to the owning node(s), which is why queries without a partition key either fail or require the dangerous ALLOW FILTERING", "WHERE clauses are optional in CQL entirely", "Partition keys are only required for INSERT statements, not SELECT"]', 1, 'This requirement is a direct consequence of Cassandra''s distributed architecture -- the partition key is literally what tells Cassandra which node(s) to route the request to, so a query without it has no efficient routing path.', 'beginner'),
('databases', 'cassandra', 'overview', 'What is a composite partition key like `PRIMARY KEY ((sensor_id, month), event_time)` used for?', '["It creates two separate, unrelated primary keys for the same table", "Combining sensor_id and month into the partition key spreads a single sensor''s data across multiple partitions (one per month) instead of one ever-growing partition -- this bucketing pattern prevents a single partition from becoming too large or too hot over time", "It removes the need for a clustering column entirely", "Composite partition keys are only valid in Cassandra 4.0 and later"]', 1, 'Bucketing (splitting what would otherwise be one huge, ever-growing partition into smaller time-bounded pieces) is one of the most important Cassandra-specific data modeling patterns, especially for time-series data.', 'intermediate'),
('databases', 'cassandra', 'overview', 'Why is Cassandra generally NOT a good fit for ad-hoc queries or complex JOINs across tables?', '["Cassandra technically supports JOINs but they are simply disabled by default configuration", "Cassandra tables are designed around specific, known query patterns (query-first modeling) rather than a normalized relational structure -- there is no JOIN operation, and querying on a field that isn''t part of the primary key requires either a secondary index (limited) or ALLOW FILTERING (a full scan), neither of which supports genuinely flexible ad-hoc querying well", "Ad-hoc queries are fully supported and are actually Cassandra''s primary strength", "JOINs are supported, just significantly slower than in a relational database"]', 1, 'This limitation is a direct tradeoff for Cassandra''s write throughput and horizontal scalability -- schemas are deliberately designed around specific known queries rather than kept flexible for arbitrary future ones.', 'beginner'),
('databases', 'cassandra', 'overview', 'What does NetworkTopologyStrategy allow that SimpleStrategy does not?', '["NetworkTopologyStrategy is only used for single-node development setups", "NetworkTopologyStrategy lets you specify a different replication factor per datacenter (e.g. 3 replicas in us-east, 3 in eu-west) -- SimpleStrategy replicates within a single datacenter only and is explicitly not recommended for production, multi-datacenter deployments", "SimpleStrategy provides stronger consistency guarantees than NetworkTopologyStrategy", "NetworkTopologyStrategy requires a paid Cassandra license, unlike SimpleStrategy"]', 1, 'Per-datacenter replication factor control is essential for genuine multi-region deployments -- SimpleStrategy''s single-datacenter design makes it explicitly unsuitable for that use case.', 'intermediate'),

-- ---------- databases/cassandra/fundamentals ----------
('databases', 'cassandra', 'fundamentals', 'Why does Cassandra data modeling start from the application''s query patterns rather than from entity relationships, unlike relational schema design?', '["This is not actually true -- Cassandra modeling works identically to relational normalization", "Because Cassandra has no JOINs and enforces the partition-key-in-WHERE-clause requirement, a table must be shaped to directly serve a specific query efficiently -- designing from entities first (as in relational normalization) tends to produce schemas that need joins Cassandra simply doesn''t have", "Query-first design is only a stylistic preference with no real technical necessity behind it", "Entity-first design works fine in Cassandra as long as secondary indexes are added afterward"]', 1, 'This is the single most important mindset shift for someone coming from relational database experience -- designing one table per query pattern, deliberately duplicating data across tables, is the correct Cassandra approach, not a workaround.', 'intermediate'),
('databases', 'cassandra', 'fundamentals', 'What is the purpose of using a prepared statement (`session.prepare(...)`) instead of a plain string query in a Cassandra driver?', '["Prepared statements are required only for DELETE operations", "A prepared statement is compiled once by the server and can then be executed many times with different parameter values, avoiding the overhead of re-parsing the query string on every execution -- the standard recommended pattern for any query run repeatedly", "Prepared statements automatically add caching that plain queries don''t get", "Prepared statements bypass the partition key requirement"]', 1, 'The compile-once, execute-many pattern is a genuine performance practice, not just a style choice -- it''s specifically recommended for any query that will run repeatedly, which in practice is most application queries.', 'beginner'),
('databases', 'cassandra', 'fundamentals', 'What guarantees "strong consistency" in Cassandra when using tunable consistency levels?', '["Setting consistency level to ONE on both reads and writes", "The relationship W + R > RF (write consistency count plus read consistency count exceeds the replication factor) guarantees at least one overlapping replica between the write and the read, ensuring the read sees the write -- commonly achieved with QUORUM on both reads and writes", "Strong consistency is impossible to achieve in Cassandra under any configuration", "Consistency level only affects write operations, never reads"]', 1, 'This W + R > RF formula is the mathematical basis for Cassandra''s tunable consistency model -- it''s why QUORUM+QUORUM with RF=3 is a commonly cited pattern for strong consistency.', 'intermediate'),
('databases', 'cassandra', 'fundamentals', 'Why would a team choose Write ONE / Read ONE for IoT sensor data but Write QUORUM / Read QUORUM for financial data?', '["The choice is arbitrary and has no real technical justification", "IoT/time-series data usually tolerates occasionally stale reads in exchange for maximum write speed, since individual readings are less critical and high-frequency -- financial data typically needs the stronger consistency guarantee that QUORUM+QUORUM provides, even at the cost of higher latency, because correctness matters more than raw throughput for that data", "ONE consistency is actually stronger than QUORUM in Cassandra''s model", "This choice only affects which datacenter data is written to, not consistency"]', 1, 'This is a genuine, deliberate tradeoff decision specific to each workload''s actual requirements -- there is no single universally correct consistency level choice, which is exactly why Cassandra makes it tunable per-query.', 'intermediate'),
('databases', 'cassandra', 'fundamentals', 'What does `default_time_to_live = 2592000` on a table definition accomplish?', '["It limits the table to a maximum of 2,592,000 rows", "It sets a table-wide default TTL (in seconds -- 2,592,000 seconds is 30 days) so that rows are automatically deleted (via tombstone) after that period unless overridden per-insert, useful for data like session events that shouldn''t be retained indefinitely", "It sets the maximum query timeout for that table specifically", "This setting only applies to materialized views, not base tables"]', 1, 'TTL is a genuinely useful Cassandra feature for data with a natural expiration (session data, cache entries, time-bounded events) -- letting the database handle expiry avoids needing a separate cleanup job.', 'beginner'),

-- ---------- databases/cassandra/intermediate ----------
('databases', 'cassandra', 'intermediate', 'What real production caveat should temper enthusiasm for materialized views as a solution to "I need to query by a non-partition-key field"?', '["Materialized views have no downsides and should always be preferred over manually maintained duplicate tables", "Cassandra''s project has long cautioned against relying on materialized views in production due to known consistency issues -- a view can drift out of sync with its base table under certain failure/repair scenarios; a manually maintained second table, written to explicitly by the application, is the generally preferred alternative", "Materialized views are deprecated and will cause a syntax error if used", "Materialized views only work with SimpleStrategy replication, never NetworkTopologyStrategy"]', 1, 'This is a real, documented caveat worth knowing before reaching for materialized views as a default solution -- they''re a genuine feature, but one with known production risk that manually-written duplicate tables avoid.', 'advanced'),
('databases', 'cassandra', 'intermediate', 'What does a lightweight transaction (LWT) using `IF NOT EXISTS` actually cost compared to a normal INSERT, and why?', '["LWTs have identical performance to normal writes with no tradeoff", "LWTs use Paxos consensus to guarantee the conditional check-and-write happens atomically across replicas, which requires additional round trips compared to a normal write -- this is why LWTs are recommended for cases that genuinely need this guarantee (uniqueness enforcement, optimistic locking) rather than as a default write pattern", "LWTs are actually faster than normal writes because they skip the commit log", "The IF NOT EXISTS clause has no effect on performance, only on the returned result"]', 1, 'Understanding that Paxos-based consensus is what makes LWTs both powerful (real atomicity) and expensive (extra round trips) is key to using them appropriately -- sparingly, for genuine conditional-write needs.', 'advanced'),
('databases', 'cassandra', 'intermediate', 'Why is `LOCAL_QUORUM` commonly preferred over `QUORUM` in a multi-datacenter Cassandra deployment?', '["LOCAL_QUORUM and QUORUM are functionally identical in every configuration", "LOCAL_QUORUM only requires a quorum of replicas within the local datacenter to acknowledge, avoiding the latency of waiting for cross-datacenter acknowledgment that a full QUORUM (spanning all datacenters) would require -- this lets applications get strong local consistency with low latency while data still replicates to other datacenters asynchronously", "LOCAL_QUORUM provides weaker consistency guarantees than ONE", "QUORUM is deprecated in favor of LOCAL_QUORUM in all Cassandra versions"]', 1, 'This is the practical mechanism that enables low-latency, geo-distributed active-active deployments -- trading strict global quorum for local quorum plus asynchronous cross-DC replication.', 'intermediate'),
('databases', 'cassandra', 'intermediate', 'Why does the CQL command `CONSISTENCY LOCAL_QUORUM;` set the consistency level for a cqlsh session rather than being attached inline to a specific SELECT statement?', '["CQL has no way to set consistency levels at all -- it is purely a driver-level concept", "In CQL/cqlsh, consistency level is a session-level (or driver-configuration-level) setting, not a per-statement clause -- there is no valid \"USING CONSISTENCY\" syntax attachable directly to a SELECT the way USING TTL attaches to an INSERT", "Consistency level can only be set once per Cassandra cluster''s entire lifetime", "LOCAL_QUORUM specifically requires a separate configuration file, unlike other consistency levels"]', 1, 'This is a real, common point of confusion -- USING TTL/USING TIMESTAMP are valid inline clauses for writes, but consistency level is configured differently (session command or driver setting), not as a per-query USING clause.', 'advanced'),
('databases', 'cassandra', 'intermediate', 'What problem does bucketing a time-series table by `(device_id, bucket)` where bucket is something like `''2024-01-15-14''` (an hourly bucket) solve?', '["It solves a security vulnerability related to timestamp injection", "Without bucketing, a single device''s partition (keyed only on device_id) would grow unbounded as more readings accumulate over time -- bucketing by a time period splits that growth across multiple partitions, keeping each partition''s size manageable and avoiding a single ever-growing \"hot\" partition", "Bucketing is purely for human readability and has no performance effect", "This pattern only matters for tables using LeveledCompactionStrategy"]', 1, 'Unbounded partition growth is a real, well-known Cassandra anti-pattern for time-series data -- bucketing is the standard, necessary fix, not an optional optimization.', 'intermediate'),

-- ---------- databases/cassandra/advanced ----------
('databases', 'cassandra', 'advanced', 'What is the practical difference between SizeTieredCompactionStrategy (STCS) and LeveledCompactionStrategy (LCS), and when would each be chosen?', '["They are functionally identical, differing only in name", "STCS merges same-sized SSTables together and suits write-heavy, infrequent-read workloads with less compaction I/O overhead; LCS maintains a leveled structure with a 10x size ratio between levels, suiting read-heavy workloads with many small updates, at the cost of more compaction I/O", "LCS is always strictly better than STCS regardless of workload", "STCS is only usable for time-series data, and LCS for all other data"]', 1, 'Choosing the wrong compaction strategy for a workload is a real, common Cassandra performance mistake -- STCS and LCS make genuinely different read/write/compaction-overhead tradeoffs suited to different access patterns.', 'advanced'),
('databases', 'cassandra', 'advanced', 'Why is TimeWindowCompactionStrategy (TWCS) specifically well-suited to time-series data combined with TTL?', '["TWCS is identical to STCS but with a different name for marketing purposes", "TWCS compacts SSTables within the same time window together, which aligns naturally with how time-series data is both written (chronologically) and expired (via TTL) -- when an entire time window''s data expires together, TWCS can drop whole SSTables efficiently rather than needing to rewrite mixed-age data during compaction", "TWCS requires disabling TTL entirely to function correctly", "TWCS only works with SimpleStrategy replication"]', 1, 'The alignment between TWCS''s time-windowed compaction and TTL-based expiration is exactly why this combination is recommended for time-series + retention-window workloads like logs and IoT data.', 'advanced'),
('databases', 'cassandra', 'advanced', 'What is a tombstone, and why can accumulating many of them degrade read performance even for data that still exists?', '["A tombstone is a corrupted data file that must be manually repaired", "A tombstone is a deletion marker written when data is deleted, since Cassandra doesn''t immediately remove data on delete -- as tombstones accumulate (especially from high-frequency deletes on the same partition), reads have to scan past increasing numbers of tombstones before reaching live data, degrading read performance even though the live data itself hasn''t changed", "Tombstones only affect write performance, never reads", "Tombstones are automatically and immediately purged the instant a delete is executed"]', 1, 'This is a genuinely common, real operational issue -- high-cardinality or high-frequency deletes on a partition are a well-known way to silently degrade that partition''s read performance over time via tombstone accumulation.', 'advanced'),
('databases', 'cassandra', 'advanced', 'Why is `nodetool repair` a routine operational task rather than something only run after an obvious problem occurs?', '["nodetool repair is purely optional and has no real operational purpose", "Repair performs anti-entropy synchronization, reconciling data differences between replicas that can accumulate over time from things like transient node unavailability, network issues, or hinted handoff limitations -- running it regularly (commonly weekly) prevents replica divergence from silently growing before it becomes an obvious, harder-to-fix problem", "Repair is only needed once, immediately after initial cluster setup", "Repair automatically runs on every write and never needs to be triggered manually"]', 1, 'Anti-entropy repair as routine maintenance (not just incident response) is a standard Cassandra operational practice specifically because replica inconsistencies can accumulate silently without it.', 'advanced'),
('databases', 'cassandra', 'advanced', 'Why does a monotonically increasing column (like a raw timestamp) make a poor partition key choice, and what commonly fixes it?', '["Monotonic columns cannot be used as partition keys at all -- this would be a syntax error", "A monotonically increasing partition key concentrates all new writes onto whichever node currently owns the latest value range, creating a write hotspot on one node while other nodes sit comparatively idle -- bucketing (combining it with another field, like device_id, into a composite partition key) or using a naturally higher-cardinality key fixes this by spreading writes across more partitions", "This only matters for read performance, never write performance", "Using a monotonic column as a partition key improves write distribution rather than harming it"]', 1, 'This hotspot problem is exactly why composite/bucketed partition keys (like (sensor_id, month) shown in this course''s Overview) exist as a standard pattern -- avoiding a single always-newest partition receiving all current writes.', 'advanced');
